#!/usr/bin/env bash
# Run on the GPU. Iterates over the protein list and calls benchmark_one_protein.sh.
set -euo pipefail
cd ~/recurrent-protein-folding
export PATH="$HOME/.local/bin:$PATH"
mkdir -p runs
LOG=runs/benchmark_overnight.log

echo '==========================================================' | tee "$LOG"
echo "START: $(date)" | tee -a "$LOG"
echo 'OVERNIGHT BENCHMARK: 20 proteins, convergence dynamics vs pLDDT' | tee -a "$LOG"
echo '==========================================================' | tee -a "$LOG"

# Protein registry: NAME|SEQUENCE|GT_PDB|GT_CHAIN|CLASS
# (PDB exists check is done per-iteration; missing files are skipped.)
PROTEINS=(
    'ubq|MQIFVKTLTGKTITLEVEPSDTIENVKAKIQDKEGIPPDQQRLIFAGKQLEDGRTLSDYNIQKESTLHLVLRLRGG|data/1UBQ.pdb|A|success'
    'mbn|VLSEGEWQLVLHVWAKVEADVAGHGQDILIRLFKSHPETLEKFDRFKHLKTEAEMKASEDLKKHGVTVLTALGAILKKKGHHEAELKPLAQSHATKHKIPIKYLEFISEAIIHVLHSRHPGDFGADAQGAMNKALELFRKDIAAKYKELGYQG|data/1MBN.pdb|A|success'
    '8fmi|GMTEYKLVVVGAGGVGKSALTIQLIQNHFVDEYDPTIEDSYRKQVVIDGETCLLDILDTAGQEEYSAMRDQYMRTGEGFLCVFAINNTKSFEDIHHYREQIKRVKDSEDVPMVLVGNKSDLPSRTVDTKQAQDLARSYGIPFIETSAKTRQGVDDAFYTLVREIRKHKEK|data/8FMI.pdb|A|success'
    'T1137s4||data/casp15/T1137/T1137s4.pdb| |failure_shallow_msa'
    'T1137s6||data/casp15/T1137/T1137s6.pdb| |failure_novel_topology'
    'T1104|QLEDSEVEAVAKGLEEYANGVTEDNFKNYVKNNFAQQEISSVEEELNVNISDSCVANKIKDEFFAISISAIVKAAQKKAWKELAVTVLRFAKANGLKTNAIIVAGQLALWAVQCG|data/casp15_rcsb/T1104.pdb|A|casp15_unknown'
    'T1120|PLTLNFGSVRLPVSADGLLHAPTAQQQLGLTQSWEAALVEHGLPETYRDFGAGPEAAVSVPDFVALAFALDTPEARRWQKRARELLARAMQGDVRVAAQIAERNPEPDARRWLAARLESTGARRELLATVARHGGEGRVYGQLGSISNRTVLGKVKATRDGLTSAELLRLAYIDTVTARAIQESEARGNAAILTLHEQVARSERQSWERAGQVQ|data/casp15_rcsb/T1120.pdb|A|casp15_unknown'
    'T1122|LCNDYGYEPNVDYPNFSTHTYWGEMETDLPGYAHFGTSWPSSGSWVEKTIGEAVRTYPMQGSDTMNEPLAEAEPLDIRAYSPDDTGNGFAAEDIRYRDDGFKDDPLTVPNCSQRGAAGGRYTYESTGGYGRGCMNVRTGSKLATTKNATWGLPLRDNGGYDLNLRTQVSGYIAPHRSGRPDTQNDLPNDSPVPYKSAAYQTGRINQRGYEDQGFDQNSWVSGAFC|data/casp15_rcsb/T1122.pdb|A|casp15_unknown'
    'T1124||data/casp15_rcsb/T1124.pdb|A|casp15_unknown'
    'T1132|MTLKEVADWLHKHGLPVSKIDFAGLLEHALADGDPLAEALDYALSHDDLIVAHGAATDPHTGAFRIEWTKNFRQLE|data/casp15_rcsb/T1132.pdb|A|casp15_unknown'
    'T1147|SDPGGPNLEKQKVAFAYSILTLAKPVQGAATDADIPMVFRDFLQPVRAACFTAGRELHRRWSMNEDTVFRLEDIAFD|data/casp15_rcsb/T1147.pdb|A|casp15_unknown'
    'T1155|QFCAGAQAWHQRMGRRPAAEEAVRRYWAACAQVRTCWPDLDPGRLDDLAFQRWVAALRDADGRARAGSALRRCRDYVSV|data/casp15_rcsb/T1155.pdb|A|casp15_unknown'
    'T1159|LCEYAGCQLDGRDYAIAFGSCEDTGLCRFGADNQQRYELLRRGDGGTNRLFGFRADEDDLALYRCRVTRFLPPALRGRSKLLDRFCQEGLNPNTAQTGFVPYSRELVPDPLDLR|data/casp15_rcsb/T1159.pdb|A|casp15_unknown'
    'T1170|MQEPAFFKDAFGNRMLPMHEIASIIRTLDDADVPDHIIQYGSIDNDIKKLISRYHVDPSSYLELRYFRLGAVQAAEMKPDIKTPSGTLPSEVKIQGVDIYDKRPSPNPTLPPGGAFKEIPYSGDLPYIRNPELYTNKLILTSGGGGNYDSYIFPDSVNHTSLAFTKAKAPSLEEISKAEIDKFSKHKHIITKEQEPCRDYLILEKILTDPVKVCDGITTLEHEFSAQEKHPYPYGSGRPGRYSQYIGGYNPHLLLSTGRVLDTAIENVDIAEYLDPNLPDAINLAY|data/casp15_rcsb/T1170.pdb|A|casp15_unknown'
    'T1173|MDIEEMASKLRDAGAIDKKDAGYWLSQHGRDLNGVRLAVDLITTAVEDVAKARPNARSDIIGPLRDLEILGNAVAILTGTGAAPNAVAVALMVRDIGNIVAVADKDVQYAVVFEEKPNGNRPLDADTLAGQLAALIASLKKVAEEAGAEVN|data/casp15_rcsb/T1173.pdb|A|casp15_unknown'
    'T1176|MQYPVASNTGTAGGTFQVTGVPALARRGGEISYLPYRVRNGNQELIVDFRKFLDPSGFAFCKILVQYLSSKGSGFSPVDYIQRMQAGGADMTIEDIPYRSVAEEELQAIVSPVFAVSAEELVAIETPLVRFAGD|data/casp15_rcsb/T1176.pdb|A|casp15_unknown'
    'T1183||data/casp15_rcsb/T1183.pdb|A|casp15_unknown'
    'T1194|MTQSGLDVISIPATFLQFADQPGSVKQYANIFAGAQRNLGGRKFFFPPADKDDRPLNRRSPSPYDFAYAQHVQNLALTSDPVFAQAANYTLAGEFAYNLDFEDKYAAIYREGKVRREYLEPGVPQRHKLLLHCEHFQRPETAEVLKLHGEKLKPLLAQYEVRRSL|data/casp15_rcsb/T1194.pdb|A|casp15_unknown'
    '1AO6||data/1AO6.pdb|A|success_large'
    '7ACN||data/pdb_targets/7acn.pdb|A|success_large'
)

success_list=()
fail_list=()

for entry in "${PROTEINS[@]}"; do
    IFS='|' read -r NAME SEQ GT_PDB GT_CHAIN CLASS <<< "$entry"
    echo '' | tee -a "$LOG"
    echo '──────────────────────────────────────────────────────────' | tee -a "$LOG"
    echo "[$NAME]  class=$CLASS  len=${#SEQ}  pdb=$GT_PDB  time=$(date +%H:%M:%S)" | tee -a "$LOG"

    if [ ! -f "$GT_PDB" ]; then
        echo "  SKIP: ground-truth PDB not found" | tee -a "$LOG"
        fail_list+=("$NAME (missing PDB)")
        continue
    fi

    if NAME="$NAME" SEQ="$SEQ" GT_PDB="$GT_PDB" GT_CHAIN="$GT_CHAIN" \
            bash scripts/benchmark_one_protein.sh 2>&1 | tee -a "$LOG"; then
        success_list+=("$NAME")
        echo "  done $NAME at $(date +%H:%M:%S)" | tee -a "$LOG"
    else
        fail_list+=("$NAME (pipeline error)")
        echo "  failed $NAME; continuing" | tee -a "$LOG"
    fi
done

echo '' | tee -a "$LOG"
echo '==========================================================' | tee -a "$LOG"
echo "END: $(date)" | tee -a "$LOG"
echo "Successful: ${#success_list[@]}" | tee -a "$LOG"
for n in "${success_list[@]}"; do echo "  ok $n" | tee -a "$LOG"; done
echo "Failed/skipped: ${#fail_list[@]}" | tee -a "$LOG"
for n in "${fail_list[@]}"; do echo "  fail $n" | tee -a "$LOG"; done
